function [fengli] = ffengli( v,h ) 
s=(2-h)*2; 
fengli=0.625*s*v.*v; 
end 
调用浮力函数 
function [ fuli ro ] = ffuli(g,h ) 
ro=1025; 
r=1; 
vpai=pi*r*r*h; 
fuli=ro*g*vpai; 
end

